const webhook = $input.first()?.json || {};
const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : {};
const headers = Object.fromEntries(Object.entries(webhook.headers || {}).map(([key, value]) => [String(key).toLowerCase(), value]));
const expectedKey = String($env.JAVEDAI_WORKFLOW_KEY || '').trim();
const presentedKey = String(headers['x-javedai-key'] || '').trim();
const DRY_RUN = true;
function safeEqual(left, right) {
  if (!left || !right || left.length !== right.length) return false;
  let mismatch = 0;
  for (let index = 0; index < left.length; index += 1) mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
  return mismatch === 0;
}
function clean(value, max = 180) {
  return String(value || '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}
function domainFrom(value) {
  const raw = clean(value, 300).toLowerCase();
  if (!raw) return '';
  try { return new URL(raw.includes('://') ? raw : 'https://' + raw).hostname.replace(/^www\./, ''); } catch { return ''; }
}
const responseEnvelope = body.response && typeof body.response === 'object' ? body.response : {};
const rawCompanies = Array.isArray(body.companies) ? body.companies : Array.isArray(responseEnvelope.companies) ? responseEnvelope.companies : [body.company || body];
const peopleLimit = Math.max(1, Math.min(10, Math.floor(Number(body.people_limit_per_company || 5) || 5)));
const seen = new Set();
const companies = rawCompanies.map((company) => {
  const item = company && typeof company === 'object' ? company : { domain: company };
  const domain = domainFrom(item.domain || item.website);
  return { company_id: clean(item.company_id || item.id, 120), company_name: clean(item.company_name || item.name, 180), domain, website: clean(item.website, 300), people_limit: peopleLimit };
}).filter((company) => {
  if (!company.domain || seen.has(company.domain)) return false;
  seen.add(company.domain);
  return true;
}).slice(0, 10);
const basisConfirmed = body.outreach_basis_confirmed === true || String(body.outreach_basis_confirmed || '').toLowerCase() === 'true';
const errors = [];
if (!expectedKey) errors.push('server_auth_not_configured');
if (!safeEqual(presentedKey, expectedKey)) errors.push('unauthorized');
if (!basisConfirmed) errors.push('outreach_basis_confirmation_required');
if (companies.length === 0) errors.push('at_least_one_valid_domain_required');
const idempotencyKey = companies.map((company) => company.domain).sort().join('|');
return [{ json: { auth_valid: safeEqual(presentedKey, expectedKey), valid: errors.length === 0, errors, dry_run: DRY_RUN, request_id: clean(body.request_id, 120) || 'people-' + Date.now().toString(36), idempotency_key: idempotencyKey, people_limit_per_company: peopleLimit, input_company_count: rawCompanies.length, unique_company_count: companies.length, companies } }];

const response = $input.first().json || {};
const company = $node['Loop Over Companies'].json;
const people = Array.isArray(response.people) ? response.people : Array.isArray(response.contacts) ? response.contacts : [];
function clean(value, max = 300) { return String(value || '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max); }
function titleScore(title, seniority) {
  const value = (String(title || '') + ' ' + String(seniority || '')).toLowerCase();
  if (/founder|owner|chief|c_suite|ceo|coo|cto|cmo/.test(value)) return 100;
  if (/vice president|\bvp\b|\bhead\b/.test(value)) return 85;
  if (/director/.test(value)) return 75;
  if (/manager/.test(value)) return 60;
  return 40;
}
const normalized = people.slice(0, company.people_limit).map((person) => {
  const firstName = clean(person.first_name, 80);
  const lastName = clean(person.last_name, 80);
  const organization = person.organization || {};
  return { person_id: clean(person.id, 120), first_name: firstName, last_name: lastName, full_name: clean(person.name || [firstName, lastName].filter(Boolean).join(' '), 180), title: clean(person.title, 180), seniority: clean(person.seniority, 80), linkedin_url: clean(person.linkedin_url, 400), city: clean(person.city, 120), state: clean(person.state, 120), country: clean(person.country, 120), company_id: clean(organization.id || company.company_id, 120), company_name: clean(organization.name || company.company_name, 180), domain: clean(organization.primary_domain || company.domain, 253).toLowerCase().replace(/^www\./, ''), email: null, phone: null, decision_maker_score: titleScore(person.title, person.seniority), source: 'apollo_people_search', needs_email_discovery: true, suppression_required: false };
}).filter((person) => person.full_name && person.domain);
return [{ json: { company_domain: company.domain, company_name: company.company_name, request_id: company.request_id, people: normalized, returned_count: normalized.length } }];

const batches = $input.all().map((item) => item.json);
const context = $node['Validate and Prepare Companies'].json;
const people = batches.flatMap((batch) => Array.isArray(batch.people) ? batch.people : []);
const seen = new Set();
const decisionMakers = people.filter((person) => {
  const key = person.person_id || person.linkedin_url || (person.full_name + '|' + person.domain).toLowerCase();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
}).sort((left, right) => right.decision_maker_score - left.decision_maker_score);
return [{ json: { response: { ok: true, status: 'complete', dry_run: false, request_id: context.request_id, company_count: context.unique_company_count, decision_maker_count: decisionMakers.length, decision_makers: decisionMakers, email_fields_intentionally_empty: true, next_workflow: 'JavedAI 04 - Email Find and Verify' } } }];
